import React from "react";
import styledCom from "styled-components";
import {NavLink} from "react-router-dom";
import StarOutlineOutlinedIcon from "@mui/icons-material/StarOutlineOutlined";
import PaidOutlinedIcon from "@mui/icons-material/PaidOutlined";
import LocalShippingOutlinedIcon from "@mui/icons-material/LocalShippingOutlined";
import TungstenOutlinedIcon from "@mui/icons-material/TungstenOutlined";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    Surface,
} from "../../ui/commonStyled/commonStyled";
import {useTranslation} from "../../i18n";

const DirectoryGrid = styledCom.div({
    display: "grid",
    gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
    gap: "12px",

    "@media (max-width: 1050px)": {
        gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
    },

    "@media (max-width: 640px)": {
        gridTemplateColumns: "1fr",
    },
});

const DirectoryLink = styledCom(NavLink)({
    display: "grid",
    gridTemplateColumns: "28px minmax(0, 1fr)",
    alignItems: "center",
    gap: "12px",
    minHeight: "72px",
    padding: "14px",
    color: "var(--color-text)",
    textDecoration: "none",
    background: "var(--color-surface)",
    border: "1px solid var(--color-border)",
    borderRadius: "12px",
    boxShadow: "var(--shadow-soft)",
    fontWeight: 760,

    "&:hover": {
        color: "var(--color-primary)",
        borderColor: "var(--color-border-strong)",
    },
});

const directoryItems = [
    {href: "/statuses", label: "Statuses", icon: StarOutlineOutlinedIcon},
    {href: "/paymentMethods", label: "Payment methods", icon: PaidOutlinedIcon},
    {href: "/deliveryMethods", label: "Delivery methods", icon: LocalShippingOutlinedIcon},
    {href: "/sources", label: "Sources", icon: TungstenOutlinedIcon},
];

const DirectoriesManagement = () => {
    const {t} = useTranslation();

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{t("Directories")}</PageTitle>
                    <PageSubtitle>
                        {t("Shared order dictionaries used by statuses, payments, delivery, and sources.")}
                    </PageSubtitle>
                </PageTitleGroup>
            </PageHeader>
            <Surface>
                <DirectoryGrid>
                    {directoryItems.map((item) => {
                        const Icon = item.icon;

                        return (
                            <DirectoryLink key={item.href} to={item.href}>
                                <Icon aria-hidden="true"/>
                                <span>{t(item.label)}</span>
                            </DirectoryLink>
                        );
                    })}
                </DirectoryGrid>
            </Surface>
        </MainDiv>
    );
};

export default DirectoriesManagement;
